# Surah Al-Hujurat (chapter 49) — part 1: ayat 1-9 (IDs 4613-4621)
SURAH = 49

ENTRIES = {
4613: (
"بسم اللہ الرّحْمٰن الرّحِیْم — اے ایمان والو اللہ اور اس کے رسول ﷺ سے آگے مت بڑھو — اور اللہ سے ڈرو — بے شک اللہ سننے والا جاننے والا ہے",
"""۱۔ ادبِ رسول — یا أیها الذین آمنوا لا تقدموا بین یدي اللہ و رسوله؛ و اتقوا اللہ؛ إن اللہ سمیع علیم۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُقَدِّمُوا بَيْنَ يَدَيِ اللَّهِ وَرَسُولِهِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ‘‘ — اے ایمان والو اللہ اور اس کے رسول ﷺ سے آگے مت بڑھو — اور اللہ سے ڈرو — بے شک اللہ سننے والا جاننے والا ہے — یعنی اے ایمان والو اللہ اور اس کے رسول ﷺ سے آگے مت بڑھو اور اللہ سے ڈرو بے شک اللہ سننے والا جاننے والا ہے۔
۳۔ عملی سبق: اللہ اور اس کے رسول ﷺ کے سامنے ادب رکھو؛ اللہ سے ڈرو۔"""
),
4614: (
"اے ایمان والو اپنی آوازیں نبی ﷺ کی آواز سے اونچا نہ کرو — اور نہ نبی ﷺ سے اتنی آواز سے بات کرو جیسے تم آپس میں ایکدوسرے سے کرتے ہو — مبادا تمہارے اعمال ضائع ہو جائیں اور تمہیں پتا بھی نہ چلے",
"""۱۔ آواز نیچی رکھو — یا أیها الذین آمنوا لا ترفعوا أصواتکم فوق صوت النبي؛ و لا تجهروا له بالقول کجهر بعضکم لبعض؛ أن تحبط أعمالکم و أنتم لا تشعرون۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ وَلَا تَجْهَرُوا لَهُ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَن تَحْبَطَ أَعْمَالُكُمْ وَأَنتُمْ لَا تَشْعُرُونَ‘‘ — اے ایمان والو اپنی آوازیں نبی ﷺ کی آواز سے اونچا نہ کرو — اور نہ نبی ﷺ سے اتنی آواز سے بات کرو جیسے تم آپس میں ایکدوسرے سے کرتے ہو — مبادا تمہارے اعمال ضائع ہو جائیں اور تمہیں پتا بھی نہ چلے — یعنی اے ایمان والو اپنی آوازیں نبی ﷺ کی آواز سے اونچا نہ کرو اور نہ نبی ﷺ سے اتنی آواز سے بات کرو جیسے تم آپس میں ایکدوسرے سے کرتے ہو مبادا تمہارے اعمال ضائع ہو جائیں اور تمہیں پتا بھی نہ چلے۔
۳۔ عملی سبق: نبی ﷺ کے سامنے آواز نیچی رکھو؛ اللہ سے ڈرو۔"""
),
4615: (
"بے شک جو لوگ رسول اللہ ﷺ کے سامنے اپنی آوازیں نیچی رکھتے ہیں — وہی وہ لوگ ہیں جن کے دلوں کو اللہ نے تقویٰ کے لیے آزمایا — ان کے لیے مغفرت اور بہت بڑا اجر ہے",
"""۱۔ خاموش ادب — إن الذین یغضوّن أصواتهم عند رسول اللہ؛ أولئك الذین امتحن اللہ قلوبهم للتقویٰ؛ لهم مغفرة و أجر عظیم۔
۲۔ ’’إِنَّ الَّذِينَ يَغُضُّونَ أَصْوَاتَهُمْ عِندَ رَسُولِ اللَّهِ أُولَٰئِكَ الَّذِينَ امْتَحَنَ اللَّهُ قُلُوبَهُمْ لِلتَّقْوَىٰ لَهُم مَّغْفِرَۃٌ وَأَجْرٌ عَظِيمٌ‘‘ — بے شک جو لوگ رسول اللہ ﷺ کے سامنے اپنی آوازیں نیچی رکھتے ہیں — وہی وہ لوگ ہیں جن کے دلوں کو اللہ نے تقویٰ کے لیے آزمایا — ان کے لیے مغفرت اور بہت بڑا اجر ہے — یعنی بے شک جو لوگ رسول اللہ ﷺ کے سامنے اپنی آوازیں نیچی رکھتے ہیں وہی وہ لوگ ہیں جن کے دلوں کو اللہ نے تقویٰ کے لیے آزمایا ان کے لیے مغفرت اور بہت بڑا اجر ہے۔
۳۔ عملی سبق: تقویٰ کے لیے نیچے آواز رکھو؛ اللہ سے ڈرو۔"""
),
4616: (
"بے شک جو لوگ تجھے حجروں کے پیچھے سے پکارتے ہیں ان میں اکثر نہیں سمجھتے",
"""۱۔ بے ادبی — إن الذین ینادونك من وراء الحجرات؛ أکثرهم لا یعقلون۔
۲۔ ’’إِنَّ الَّذِينَ يُنَادُونَكَ مِن وَرَاءِ الْحُجُرَاتِ أَكْثَرُهُمْ لَا يَعْقِلُونَ‘‘ —بے شک جو لوگ تجھے حجروں کے پیچھے سے پکارتے ہیں ان میں اکثر نہیں سمجھتے۔
۳۔ عملی سبق: نبی ﷺ کو پکارنے کا ادب سیکھو؛ اللہ سے ڈرو۔"""
),
4617: (
"اور اگر وہ صبر کرتے یہاں تک کہ تو خود ان کے پاس نکل آتا تو ان کے لیے بہتر ہوتا — اور اللہ بخشنے والا مہربان ہے",
"""۱۔ صبر کی بھلائی — و لو أنهم صبروا حتی تخرج إلیهم لکان خیرًا لهم؛ واللہ غفور رحیم۔
۲۔ ’’وَلَوْ أَنَّهُمْ صَبَرُوا حَتَّىٰ تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًا لَّهُمْ وَاللَّهُ غَفُورٌ رَّحِيمٌ‘‘ — اور اگر وہ صبر کرتے یہاں تک کہ تو خود ان کے پاس نکل آتا تو ان کے لیے بہتر ہوتا — اور اللہ بخشنے والا مہربان ہے — یعنی اور اگر وہ صبر کرتے یہاں تک کہ تو خود ان کے پاس نکل آتا تو ان کے لیے بہتر ہوتا اور اللہ بخشنے والا مہربان ہے۔
۳۔ عملی سبق: صبر کرو؛ اللہ سے ڈرو۔"""
),
4618: (
"اے ایمان والو اگر کوئی فاسق تمہارے پاس کوئی خبر لائے تو تحقیق کرو — مبادا نادانستہ کسی قوم کو نقصان پہنچا دو — پھر اپنے کیے پر نادم ہو جاؤ",
"""۱۔ تحقیقِ خبر — یا أیها الذین آمنوا إن جاءكم فاسق بنبإ فتبینوا؛ أن تصیبوا قومًا بجهالۃ؛ فتصبحوا علی ما فعلتم نادمین۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِن جَاءَكُمْ فَاسِقٌ بِنَبَإٍ فَتَبَيَّنُوا أَن تُصِيبُوا قَوْمًا بِجَهَالَۃٍ فَتُصْبِحُوا عَلَىٰ مَا فَعَلْتُمْ نَادِمِينَ‘‘ — اے ایمان والو اگر کوئی فاسق تمہارے پاس کوئی خبر لائے تو تحقیق کرو — مبادا نادانستہ کسی قوم کو نقصان پہنچا دو — پھر اپنے کیے پر نادم ہو جاؤ — یعنی اے ایمان والو اگر کوئی فاسق تمہارے پاس کوئی خبر لائے تو تحقیق کرو مبادا نادانستہ کسی قوم کو نقصان پہنچا دو پھر اپنے کیے پر نادم ہو جاؤ۔
۳۔ عملی سبق: ہر خبر کی تحقیق کرو؛ اللہ سے ڈرو۔"""
),
4619: (
"اور جان لو کہ تمہارے درمیان اللہ کے رسول ﷺ ہیں — اگر وہ بہت سے معاملات میں تمہاری بات مان لیتے تو تم مشقت میں پڑ جاتے — لیکن اللہ نے تمہارے لیے ایمان کو محبوب بنایا اور اسے تمہارے دلوں میں مزین کیا — اور تمہیں کفر فسق اور نافرمانی سے نفرت دلائی — یہی لوگ ہدایت یافتہ ہیں",
"""۱۔ اللہ کی نعمت — و اعلموا أن فيکم رسول اللہ؛ لو یطیعكم في کثیر من الأمر لعنِتّم؛ ولکن اللہ حبّب إلیکم الإیمان و زینہ في قلوبکم؛ و کرّه إلیکم الکفر و الفسوق و العصیان؛ أولئك هم الراشدون۔
۲۔ ’’وَاعْلَمُوا أَنَّ فِيكُمْ رَسُولَ اللَّهِ لَوْ يُطِيعُكُمْ فِي كَثِيرٍ مِّنَ الْأَمْرِ لَعَنِتُّمْ وَلَٰكِنَّ اللَّهَ حَبَّبَ إِلَيْكُمُ الْإِيمَانَ وَزَيَّنَهُ فِي قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ أُولَٰئِكَ هُمُ الرَّاشِدُونَ‘‘ — اور جان لو کہ تمہارے درمیان اللہ کے رسول ﷺ ہیں — اگر وہ بہت سے معاملات میں تمہاری بات مان لیتے تو تم مشقت میں پڑ جاتے — لیکن اللہ نے تمہارے لیے ایمان کو محبوب بنایا اور اسے تمہارے دلوں میں مزین کیا — اور تمہیں کفر فسق اور نافرمانی سے نفرت دلائی — یہی لوگ ہدایت یافتہ ہیں — یعنی اور جان لو کہ تمہارے درمیان اللہ کے رسول ﷺ ہیں اگر وہ بہت سے معاملات میں تمہاری بات مان لیتے تو تم مشقت میں پڑ جاتے لیکن اللہ نے تمہارے لیے ایمان کو محبوب بنایا اور اسے تمہارے دلوں میں مزین کیا اور تمہیں کفر فسق اور نافرمانی سے نفرت دلائی یہی لوگ ہدایت یافتہ ہیں۔
۳۔ عملی سبق: ایمان کی نعمت کا شکر کرو؛ اللہ سے ڈرو۔"""
),
4620: (
"اللہ کی طرف سے فضل اور نعمت — اور اللہ جاننے والا حکمت والا ہے",
"""۱۔ فضلِ الٰہی — فضلًا من اللہ و نعمۃ؛ واللہ علیم حکیم۔
۲۔ ’’فَضْلًا مِّنَ اللَّهِ وَنِعْمَۃً وَاللَّهُ عَلِيمٌ حَكِيمٌ‘‘ — اللہ کی طرف سے فضل اور نعمت — اور اللہ جاننے والا حکمت والا ہے — یعنی اللہ کی طرف سے فضل اور نعمت اور اللہ جاننے والا حکمت والا ہے۔
۳۔ عملی سبق: اللہ کے فضل کا شکر کرو؛ اللہ سے ڈرو۔"""
),
4621: (
"اور اگر مؤمنین کی دو جماعتیں آپس میں لڑ پڑیں تو ان کے درمیان صلح کراؤ — پھر اگر ان میں سے ایک دوسری پر زیادتی کرے تو زیادتی کرنے والی سے لڑو یہاں تک کہ وہ اللہ کے حکم کی طرف واپس آ جائے — پھر اگر وہ واپس آ جائے تو ان کے درمیان عدل کے ساتھ صلح کراؤ — اور انصاف کرو — بے شک اللہ انصاف کرنے والوں سے محبت کرتا ہے",
"""۱۔ صلحِ مومنین — و إن طائفتان من المؤمنین اقتتلوا فأصلحوا بینهما؛ فإن بغت إحداهما علی الأخری فقاتلوا التي تبغي حتی تفئ إلی أمر اللہ؛ فإن فاءت فأصلحوا بینهما بالعدل؛ و أقسطوا؛ إن اللہ یحب المقسطین۔
۲۔ ’’وَإِن طَائِفَتَانِ مِنَ الْمُؤْمِنِينَ اقْتَتَلُوا فَأَصْلِحُوا بَيْنَهُمَا فَإِن بَغَتْ إِحْدَاهُمَا عَلَى الْأُخْرَىٰ فَقَاتِلُوا الَّتِي تَبْغِي حَتَّىٰ تَفِيءَ إِلَىٰ أَمْرِ اللَّهِ فَإِن فَاءَتْ فَأَصْلِحُوا بَيْنَهُمَا بِالْعَدْلِ وَأَقْسِطُوا إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ‘‘ — اور اگر مؤمنین کی دو جماعتیں آپس میں لڑ پڑیں تو ان کے درمیان صلح کراؤ — پھر اگر ان میں سے ایک دوسری پر زیادتی کرے تو زیادتی کرنے والی سے لڑو یہاں تک کہ وہ اللہ کے حکم کی طرف واپس آ جائے — پھر اگر وہ واپس آ جائے تو ان کے درمیان عدل کے ساتھ صلح کراؤ — اور انصاف کرو — بے شک اللہ انصاف کرنے والوں سے محبت کرتا ہے — یعنی اور اگر مؤمنین کی دو جماعتیں آپس میں لڑ پڑیں تو ان کے درمیان صلح کراؤ پھر اگر ان میں سے ایک دوسری پر زیادتی کرے تو زیادتی کرنے والی سے لڑو یہاں تک کہ وہ اللہ کے حکم کی طرف واپس آ جائے پھر اگر وہ واپس آ جائے تو ان کے درمیان عدل کے ساتھ صلح کراؤ اور انصاف کرو بے شک اللہ انصاف کرنے والوں سے محبت کرتا ہے۔
۳۔ عملی سبق: مسلمانوں کی آپس کی جنگ میں صلح کرواؤ؛ انصاف کرو؛ اللہ سے ڈرو۔"""
),
}
